def finish(self, frame):
    completed = False
    try:
        if frame.drive() != 0:
            raise FrontUnknown('front root unexpectedly yielded')
        completed = True
        return frame.take()
    except BaseException:
        completed = False
        raise
    finally:
        frame.close(release=completed)

