@property
def normalization_report(self):
    checked = verify_program(self)
    core = checked.as_dict()
    original = (decode_internal_canonical(checked.structured_bytes, max_nodes=MAX_NODES, max_depth=MAX_DEPTH)
                if checked.structured_bytes is not None else core)
    return {"input_sha256": checked.input_sha256,
            "core_sha256": checked.sha256,
            "input_schema": original["schema"],
            "input_profile": profile_for_schema(original["schema"]),
            "core_schema": core["schema"],
            "core_profile": profile_for_schema(core["schema"]),
            "structured_elaboration_rechecked": checked.structured_bytes is not None,
            "primitive_core_rechecked": True,
            "source_ast_required": False,
            "public_scalar_entrypoints": sorted(checked.scalar_entrypoints)}

original_pending_guard.text:
def step(self):
    if self.closed and not self._retiring:
        raise RuntimeError('native machine-plan frame is closed')
    if self.pending is not None and not self.completed:
        raise RuntimeError('native machine-plan observation lacks its actual acknowledgement')
    try:
        if not self._started:
            result = self._invoke(0)
            self._started = True
        elif self._status == 2:
            if not self._yield_taken:
                raise RuntimeError('native machine-plan yielded value was not consumed')
            self._yield_taken = False
            result = self._invoke(3)
        else:
            if self.reply is None or self.pending is None:
                raise RuntimeError('native machine-plan continuation has no issued result')
            result = self._invoke(1, *self.reply)
        self._accept_result(result)
        return result
    except BaseException:
        self._uncertain = True
        self.close(release=False)
        raise

